def _resolve_template(self, template: str) -> t.Tuple[str, str]:
    """Resolve aliases and the path transformation for a template name.

    Returns a tuple of ``(resolved_template, name_for_errors)`` where
    ``resolved_template`` is the name to use for the actual lookup and
    ``name_for_errors`` is the name to use in :exc:`TemplateNotFound`
    errors raised when the template cannot be found.
    """
    name_for_errors = template
    if template in self._aliases:
        template = self._aliases[template]
        name_for_errors = template
    template = self._transform_path(template)
    return template, name_for_errors

