from a different location.

:param loaders: A sequence of loaders to try in order.
:param path_transform: An optional callable that receives the
    template path and returns a transformed path used for the
    actual template resolution. Applied at the top level before
    delegating to the child loaders.
"""

def __init__(
    self,
    loaders: t.Sequence[BaseLoader],
    path_transform: t.Optional[t.Callable[[str], str]] = None,
) -> None:
    super().__init__()
    self.loaders = loaders
    self._path_transform = path_transform

def get_source(
    self, environment: "Environment", template: str
) -> t.Tuple[str, t.Optional[str], t.Optional[t.Callable[[], bool]]]:
    template, name_for_errors = self._resolve_template(template)
    for loader in self.loaders:
        try:
            return loader.get_source(environment, template)
        except TemplateNotFound:
            pass
    raise TemplateNotFound(name_for_errors)

